import logging

log = logging.getLogger(__name__)


def run_forever(queue) -> None:
    """Top-level worker loop: one bad job must never stop the worker."""
    while True:
        job = queue.get()
        try:
            job.run()
        except Exception:
            log.exception("job %s failed", job.id)
            queue.dead_letter(job)
